            tail->next = new IntSLLNode(el);
            tail = tail->next;
        } else head = tail = new IntSLLNode(el);
    }
    int deleteFromHead() { 
        int el = head->info;
        IntSLLNode *tmp = head;
        if (head == tail) head = tail = nullptr;
        else head = head->next;
        delete tmp;
        return el;
    }
